if (element.querySelector('.custom-save-btn')) return;

var btn = document.createElement('button');
btn.className = 'custom-save-btn';
btn.type = 'button';
btn.textContent = 'Save';
btn.style.cssText = 'position:absolute;top:8px;right:8px;z-index:10;background:#E60023;color:#fff;border:none;border-radius:18px;padding:6px 14px;font-size:13px;font-weight:600;cursor:pointer;box-shadow:0 2px 8px rgba(0,0,0,0.25);transition:background 0.2s;pointer-events:auto;line-height:1;';

btn.addEventListener('mouseenter', function() { btn.style.background = '#ad081b'; });
btn.addEventListener('mouseleave', function() { btn.style.background = '#E60023'; });

var pinCard = element.closest('[data-test-id="pin"]');
if (pinCard) {
  var pinId = pinCard.getAttribute('data-test-pin-id');
  if (pinId) {
    btn.addEventListener('click', function(e) {
      e.preventDefault();
      e.stopPropagation();
      // Trigger the save by clicking the existing more-actions button or opening the pin
      var deeplink = pinCard.querySelector('[data-test-id="deeplink-wrapper"] a');
      if (deeplink) {
        window.open(deeplink.href, '_blank');
      }
    });
  }
}

element.style.position = 'relative';
element.appendChild(btn);
